ttachment or unattached object with no record-level demo provenance.","database_created_at":"2026-10-10T22:53:30.970930+00:00"},{"path":"98dff58a-df40-4894-a23b-2cb6cdd6ce87/d80a3b73-c810-4dcf-8b63-fc647f5c7c1e.webp","id":"b71c8062-8ff7-4e79-981d-a92273ab4b71","created_at":"2026-10-11T01:07:13.384Z","owner_id":"98dff58a-df40-4894-a23b-2cb6cdd6ce87","referenced_by_listing_ids":["596ca3f6-3383-4781-a98d-ef12bbe50a15"],"proposed_action":"preserve","reason":"Unconfirmed listing attachment or unattached object with no record-level demo provenance.","database_created_at":"2026-10-11T01:07:13.384129+00:00"},{"path":"98dff58a-df40-4894-a23b-2cb6cdd6ce87/da139a63-0dd9-4968-acb2-ed57b8082a78.webp","id":"98809965-0762-42f0-a583-424228d6849f","created_at":"2026-10-10T21:44:33.154Z","owner_id":"98dff58a-df40-4894-a23b-2cb6cdd6ce87","referenced_by_listing_ids":[],"proposed_action":"preserve","reason":"Unconfirmed listing attachment or unattached object with no record-level demo provenance.","database_created_at":"2026-10-10T21:44:33.154386+00:00"}],"preserve_listings":[{"id":"596ca3f6-3383-4781-a98d-ef12bbe50a15","organizer_id":"98dff58a-df40-4894-a23b-2cb6cdd6ce87","title":"Houston Room","portions_total":6,"photo_path":"98dff58a-df40-4894-a23b-2cb6cdd6ce87/d80a3b73-c810-4dcf-8b63-fc647f5c7c1e.webp","reason":"No explicit synthetic provenance; preserve regardless of apparent test-like text or owner account."},{"id":"93826203-b449-4dbc-beba-38e0fcd18c2f","organizer_id":"8e7289b4-9f90-4453-b583-fb8adf0f8030","title":"Leftover Pizza Boxes","portions_total":9,"photo_path":null,"reason":"No explicit synthetic provenance; preserve regardless of apparent test-like text or owner account."}],"preserve_locations":[{"id":"06d15a9b-b89f-4204-9147-fdc9776a6592","name":"Melcher Hall","latitude":29.7210757,"longitude":-95.339903,"google_maps_url":"https://www.google.com/maps/place/Melcher+Hall/@29.7215259,-95.3429822,17z/data=!4m6!3m5!1s0x8640bfac6704896d:0xd3ac97f07af27f80!8m2!3d29.7210757!4d-95.339903!16s%2Fg%2F11vcl50v45?entry=ttu&g_ep=EgoyMDI2MTAwNy4wIKXMDSoASAFQAw%3D%3D"},{"id":"06dbb97b-a402-4001-b926-975e93d794a3","name":"L2D2 Engineering Lecture Hall","latitude":29.7227294,"longitude":-95.3408917,"google_maps_url":"https://www.google.com/maps/place/L2D2+Engineering+Lecture+Hall/@29.7228562,-95.3439618,17z/data=!4m10!1m2!2m1!1sengineering+building+2+uh!3m6!1s0x8640bf288b5e4641:0x9450ea472ca232fd!8m2!3d29.7227294!4d-95.3408917!15sChllbmdpbmVlcmluZyBidWlsZGluZyAyIHVokgEVdW5pdmVyc2l0eV9kZXBhcnRtZW504AEA!16s%2Fg%2F11h6wglmyk?entry=ttu&g_ep=EgoyMDI2MTAwNy4wIKXMDSoASAFQAw%3D%3D"},{"id":"6f050b6f-fa4c-4ba2-84ca-7164a3ea0ac0","name":"Student Center North","latitude":29.7208509,"longitude":-95.3407878,"google_maps_url":"https://www.google.com/maps/place/Student+Center+North/@29.7208509,-95.3433627,17z/data=!4m6!3m5!1s0x8640be5a13bf633f:0xf34de69146bacb09!8m2!3d29.7208509!4d-95.3407878!16s%2Fg%2F11c594k13l?entry=ttu&g_ep=EgoyMDI2MTAwNy4wIKXMDSoASAFQAw%3D%3D"},{"id":"8056d7dd-5309-4a9b-9c32-4ce7c6d33efc","name":"M.D. Anderson Library","latitude":29.721084,"longitude":-95.342048,"google_maps_url":"https://www.google.com/maps/place/M.D.+Anderson+Library/@29.7232568,-95.3462471,17z/data=!4m6!3m5!1s0x8640c0748ba2522f:0x2a3f0ce5297e9c3a!8m2!3d29.721084!4d-95.342048!16s%2Fm%2F04183nz?entry=ttu&g_ep=EgoyMDI2MTAwNy4wIKXMDSoASAFQAw%3D%3D"},{"id":"984dfd34-f264-40f8-b3ae-94b09d514e93","name":"Science & Engineering Classroom Building (SEC)","latitude":29.7233249,"longitude":-95.346109,"google_maps_url":"https://www.google.com/maps/place/Science+%26+Engineering+Classroom+Building+(SEC)/@29.721084,-95.3446229,17z/data=!4m14!1m7!3m6!1s0x8640c0748ba2522f:0x2a3f0ce5297e9c3a!2sM.D.+Anderson+Library!8m2!3d29.721084!4d-95.342048!16s%2Fm%2F04183nz!3m5!1s0x8640be5689fcfe11:0x1e4f121759fbcfa1!8m2!3d29.7233249!4d-95.346109!16s%2Fg%2F11bwpzn9qb?entry=ttu&g_ep=EgoyMDI2MTAwNy4wIKXMDSoASAFQAw%3D%3D"},{"id":"a3c84aaa-bf83-485a-b8f3-fa414e23ddba","name":"A.D. Bruce Religion Center","latitude":29.719255,"longitude":-95.3452524,"google_maps_url":"https://www.google.com/maps/place/A.D.+Bruce+Religion+Center+at+the+University+of+Houston/@29.7197767,-95.3445519,17.38z/data=!4m14!1m7!3m6!1s0x8640c0748ba2522f:0x2a3f0ce5297e9c3a!2sM.D.+Anderson+Library!8m2!3d29.721084!4d-95.342048!16s%2Fm%2F04183nz!3m5!1s0x8640be510953f395:0x591f141fb5e402d1!8m2!3d29.719255!4d-95.3452524!16s%2Fg%2F1tdb4ntd?entry=ttu&g_ep=EgoyMDI2MTAwNy4wIKXMDSoASAFQAw%3D%3D"},{"id":"d7e70feb-1127-4d70-b984-c7b5d8ed8da0","name":"CBB (Classroom and Business Building)","latitude":29.7215259,"longitude":-95.3404073,"google_maps_url":"https://www.google.com/maps/place/Classroom+and+Business+Building/@29.7208509,-95.3433627,17z/data=!4m6!3m5!1s0x8640be5a16a63e39:0x942d5cbac1d59b1a!8m2!3d29.7215259!4d-95.3404073!16s%2Fg%2F11byck36km?entry=ttu&g_ep=EgoyMDI2MTAwNy4wIKXMDSoASAFQAw%3D%3D"},{"id":"eb6e2bd5-2e8e-4fe8-b447-a3ab705b39f7","name":"Student Center South","latitude":29.7200622,"longitude":-95.3410239,"google_maps_url":"https://www.google.com/maps/place/Student+Center+South/@29.7200622,-95.3435988,17z/data=!3m2!4b1!5s0x8640be5a14605ebd:0x699b88500f18f1c1!4m6!3m5!1s0x8640be5a378d489b:0x2fbf3e96e13ad6ca!8m2!3d29.7200622!4d-95.3410239!16s%2Fg%2F11_tpzvt0?entry=ttu&g_ep=EgoyMDI2MTAwNy4wIKXMDSoASAFQAw%3D%3D"},{"id":"fc536109-3c24-4023-b65e-824fb94c3980","name":"Engineering Building 1","latitude":29.7228562,"longitude":-95.3413869,"google_maps_url":"https://www.google.com/maps/place/Engineering+Building+1-Cullen+College+of+Engineering/@29.7228562,-95.3439618,17z/data=!3m1!4b1!4m6!3m5!1s0x8640be59ddbfffff:0xf65ddb544650f173!8m2!3d29.7228562!4d-95.3413869!16s%2Fg%2F1ym82kz9j?entry=ttu&g_ep=EgoyMDI2MTAwNy4wIKXMDSoASAFQAw%3D%3D"}]}$demo17$::jsonb AS data),
listing_rows AS (SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) AS data FROM public.listings l),
reservation_rows AS (SELECT coalesce(jsonb_agg((to_jsonb(r) - 'pickup_code') || jsonb_build_object('private_code_fingerprint',md5(r.pickup_code)) ORDER BY r.id),'[]'::jsonb) AS data FROM public.reservations r),
location_rows AS (SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) AS data FROM public.locations l),
profile_rows AS (SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]'::jsonb) AS data FROM public.profiles p),
account_ids AS (SELECT coalesce(jsonb_agg(u.id ORDER BY u.id),'[]'::jsonb) AS data FROM auth.users u),
photo_rows AS (SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'path',o.name,'owner_id',o.owner_id,'created_at',o.created_at,'updated_at',o.updated_at,'metadata',o.metadata) ORDER BY o.name),'[]'::jsonb) AS data FROM storage.objects o WHERE o.bucket_id='food-photos'),
dependency_schema AS (SELECT jsonb_build_object('foreign_keys',coalesce((SELECT jsonb_agg(jsonb_build_object('name',c.conname,'table',c.conrelid::regclass::text,'definition',pg_get_constraintdef(c.oid)) ORDER BY c.oid) FROM pg_constraint c WHERE c.contype='f' AND c.confrelid IN ('public.listings'::regclass,'public.reservations'::regclass)),'[]'::jsonb),'custom_triggers',coalesce((SELECT jsonb_agg(pg_get_triggerdef(t.oid) ORDER BY t.oid) FROM pg_trigger t WHERE t.tgrelid IN ('public.listings'::regclass,'public.reservations'::regclass) AND NOT t.tgisinternal),'[]'::jsonb)) AS data),
snapshot AS (SELECT jsonb_build_object('listings',l.data,'reservations',r.data,'locations',loc.data,'profiles',p.data,'account_ids',a.data,'photos',ph.data,'dependency_schema',ds.data) AS data FROM listing_rows l CROSS JOIN reservation_rows r CROSS JOIN location_rows loc CROSS JOIN profile_rows p CROSS JOIN account_ids a CROSS JOIN photo_rows ph CROSS JOIN dependency_schema ds),
expected_records AS (
 SELECT 'listing' AS kind, e AS expected FROM manifest m CROSS JOIN LATERAL jsonb_array_elements(m.data->'delete_listings') e
 UNION ALL SELECT 'reservation',e FROM manifest m CROSS JOIN LATERAL jsonb_array_elements(m.data->'delete_reservations') e
 UNION ALL SELECT 'preserved_listing',e-'reason' FROM manifest m CROSS JOIN LATERAL jsonb_array_elements(m.data->'preserve_listings') e
 UNION ALL SELECT 'location',e FROM manifest m CROSS JOIN LATERAL jsonb_array_elements(m.data->'preserve_locations') e
),
actual_records AS (
 SELECT 'listing' AS kind,e AS actual FROM listing_rows r CROSS JOIN LATERAL jsonb_array_elements(r.data) e
 UNION ALL SELECT 'reservation',e FROM reservation_rows r CROSS JOIN LATERAL jsonb_array_elements(r.data) e
 UNION ALL SELECT 'preserved_listing',e FROM listing_rows r CROSS JOIN LATERAL jsonb_array_elements(r.data) e
 UNION ALL SELECT 'location',e FROM location_rows r CROSS JOIN LATERAL jsonb_array_elements(r.data) e
),
record_differences AS (
 SELECT e.kind, e.expected->>'id' AS id, coalesce(k.key,'missing record') AS field
 FROM expected_records e LEFT JOIN actual_records a ON a.kind=e.kind AND a.actual->>'id'=e.expected->>'id'
 LEFT JOIN LATERAL jsonb_each(e.expected) k ON true
 WHERE a.actual IS NULL OR CASE
 WHEN k.key IN ('created_at','collected_at','pickup_deadline') THEN (a.actual->>k.key)::timestamptz IS DISTINCT FROM (k.value#>>'{}')::timestamptz
 ELSE a.actual->k.key IS DISTINCT FROM k.value END
),
scoped_reservations AS (SELECT r.* FROM public.reservations r WHERE r.listing_id IN (SELECT (e->>'id')::uuid FROM manifest m CROSS JOIN LATERAL jsonb_array_elements(m.data->'delete_listings') e)),
unexpected_dependencies AS (SELECT r.id FROM scoped_reservations r WHERE r.id NOT IN (SELECT (e->>'id')::uuid FROM manifest m CROSS JOIN LATERAL jsonb_array_elements(m.data->'delete_reservations') e)),
unexpected_listings AS (SELECT l.id FROM public.listings l WHERE l.id NOT IN (SELECT (e->>'id')::uuid FROM manifest m CROSS JOIN LATERAL jsonb_array_elements((m.data->'delete_listings')||(m.data->'preserve_listings')) e)),
photo_checks AS (
 SELECT e->>'path' AS path,e->>'proposed_action' AS proposed_action,
 EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='food-photos' AND o.name=e->>'path' AND o.id=(e->>'id')::uuid AND o.created_at=coalesce(e->>'database_created_at',e->>'created_at')::timestamptz AND o.owner_id IS NOT DISTINCT FROM e->>'owner_id') AS identity_matches,
 coalesce((SELECT jsonb_agg(l.id ORDER BY l.id) FROM public.listings l WHERE l.photo_path=e->>'path'),'[]'::jsonb) AS actual_references,
 (SELECT coalesce(jsonb_agg(v ORDER BY v),'[]'::jsonb) FROM jsonb_array_elements(e->'referenced_by_listing_ids') v) AS expected_references
 FROM manifest m CROSS JOIN LATERAL jsonb_array_elements(m.data->'photo_objects') e
),
impact AS (SELECT jsonb_build_object('posted_portions',coalesce(sum(l.portions_total),0),'collected_portions',(SELECT count(*) FROM public.reservations WHERE status='collected'),'active_reserved_portions',(SELECT count(*) FROM public.reservations r JOIN public.listings x ON x.id=r.listing_id WHERE r.status='reserved' AND x.pickup_deadline>now())) AS data FROM public.listings l),
report AS (SELECT jsonb_build_object(
 'target_host',m.data->>'target_supabase_host',
 'database_role',current_user,
 'administrative_visibility',(SELECT rolsuper OR rolbypassrls FROM pg_roles WHERE rolname=current_user),
 'read_at',now(),
 'snapshot_fingerprint',md5(s.data::text),
 'counts',jsonb_build_object('listings',jsonb_array_length(s.data->'listings'),'reservations',jsonb_array_length(s.data->'reservations'),'locations',jsonb_array_length(s.data->'locations'),'profiles',jsonb_array_length(s.data->'profiles'),'accounts',jsonb_array_length(s.data->'account_ids'),'food_photo_objects_all_prefixes',jsonb_array_length(s.data->'photos')),
 'impact',i.data,
 'dependency_schema',s.data->'dependency_schema',
 'record_differences',coalesce((SELECT jsonb_agg(to_jsonb(d)) FROM record_differences d),'[]'::jsonb),
 'unexpected_scoped_reservations',coalesce((SELECT jsonb_agg(id ORDER BY id) FROM unexpected_dependencies),'[]'::jsonb),
 'unexpected_listings',coalesce((SELECT jsonb_agg(id ORDER BY id) FROM unexpected_listings),'[]'::jsonb),
 'photo_checks',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY path) FROM photo_checks p),'[]'::jsonb),
 'preserved_reservations',coalesce((SELECT jsonb_agg(to_jsonb(r)-'pickup_code' ORDER BY r.id) FROM public.reservations r WHERE r.listing_id IN (SELECT (e->>'id')::uuid FROM jsonb_array_elements(m.data->'preserve_listings') e)),'[]'::jsonb),
 'scoped_counts',jsonb_build_object('listings',54,'portions',67,'reservations',(SELECT count(*) FROM scoped_reservations),'collected',(SELECT count(*) FROM scoped_reservations WHERE status='collected')),
 'existing_replacement_ids',coalesce((SELECT jsonb_agg(id ORDER BY id) FROM public.listings WHERE title LIKE 'DEMO #17 —%'),'[]'::jsonb),
 'ready_for_manifest_review',(SELECT rolsuper OR rolbypassrls FROM pg_roles WHERE rolname=current_user) AND NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid IN ('public.listings'::regclass,'public.reservations'::regclass) AND NOT t.tgisinternal) AND NOT EXISTS(SELECT 1 FROM pg_constraint c WHERE c.contype='f' AND c.confrelid IN ('public.listings'::regclass,'public.reservations'::regclass) AND NOT (c.conrelid='public.reservations'::regclass AND c.confrelid='public.listings'::regclass AND c.confdeltype='a' AND c.conkey=ARRAY[(SELECT attnum FROM pg_attribute WHERE attrelid='public.reservations'::regclass AND attname='listing_id')]::smallint[])) AND NOT EXISTS(SELECT 1 FROM record_differences) AND NOT EXISTS(SELECT 1 FROM unexpected_dependencies) AND NOT EXISTS(SELECT 1 FROM unexpected_listings) AND NOT EXISTS(SELECT 1 FROM photo_checks WHERE NOT identity_matches OR actual_references IS DISTINCT FROM expected_references) AND i.data='{"posted_portions":82,"collected_portions":25,"active_reserved_portions":0}'::jsonb
 ) AS data FROM manifest m CROSS JOIN snapshot s CROSS JOIN impact i)
SELECT jsonb_pretty(data) AS demo17_preflight_report FROM report;
COMMIT;
